{{#if {{equal::{{chat_index}}::{{lastmessageid}}}}}}</body>
<div class="risu-custom-interface rofan-theme">
    <input type="checkbox" id="side-panel-toggle" style="display:none;">

    <label for="side-panel-toggle" class="floating-btn" title="설정">
        <span class="icon-glow">⚙️</span>
    </label>

    <div class="side-panel">
        <div class="panel-inner-border"> 
            <div class="panel-header">
                <h2>System Settings</h2>
                <div class="ornament-line">♦ ──────── ♦</div>
            </div>

            <div class="panel-body">
                <div class="setting-row">
                    <div class="setting-info">
                        <div class="setting-title">📖 원작 시나리오 로어북</div>
                        <div class="setting-desc">소설 원작 시나리오 로어북을 활성화합니다.</div>
                        <div class="current-status">
                            상태: 
                            {{#if {{equal::{{getvar::original_mode}}::1}}}}
                                <span class="status-on">활성화</span>
                            {{/if}}
                            {{#if {{equal::{{getvar::original_mode}}::0}}}}
                                <span class="status-off">비활성화</span>
                            {{/if}}
                        </div>
                    </div>
                    <div class="setting-controls">
                        {{button::ON::originalon}}
                        {{button::OFF::originaloff}}
                    </div>
                </div>

                <div class="divider-ornament"></div>

                <div class="setting-row">
                    <div class="setting-info">
                        <div class="setting-title">✔️ 상태창 출력</div>
                        <div class="setting-desc">상태창 출력을 활성화합니다.</div>
                        <div class="current-status">
                            상태: 
                            {{#if {{equal::{{getvar::status_window}}::1}}}}
                                <span class="status-on">활성화</span>
                            {{/if}}
                            {{#if {{equal::{{getvar::status_window}}::0}}}}
                                <span class="status-off">비활성화</span>
                            {{/if}}
                        </div>
                    </div>
                    <div class="setting-controls">
                        {{button::ON::statuswindowon}}
                        {{button::OFF::statuswindowoff}}
                    </div>
                </div>                
            </div>
        </div>
    </div>
</div>

<style>
    /* --- 로맨스 판타지 테마 CSS --- */

    /* 폰트 및 기본 컬러 */
    .risu-custom-interface.rofan-theme {
        font-family: 'Georgia', 'Batang', serif; /* 명조체 계열 */
        color: #e0d0b0; /* 낡은 종이색 글씨 */
    }

    /* 1. 플로팅 버튼 */
    .floating-btn {
        position: fixed;
        top: 15%;
        right: 0;
        width: 45px;
        height: 45px;
        background: linear-gradient(135deg, #2a2a35 0%, #15151e 100%);
        border: 2px solid #c5a059; /* 금색 테두리 */
        border-right: none;
        border-radius: 12px 0 0 12px;
        text-align: center;
        line-height: 45px;
        cursor: pointer;
        z-index: 10001;
        transition: all 0.3s ease;
        font-size: 22px;
        box-shadow: -2px 2px 8px rgba(0,0,0,0.5);
    }

    .floating-btn:hover {
        width: 55px;
        background: #353545;
        text-shadow: 0 0 5px #ffd700;
    }

    /* 2. 패널 본체 */
    .side-panel {
        position: fixed;
        top: 15%;
        right: -340px; 
        width: 320px;
        /* 내용이 길어지면 스크롤이 생기게 하는 핵심 코드 */
        max-height: 80vh; /* 화면 높이의 80%까지만 차지 */
        overflow-y: auto; /* 세로 스크롤 허용 */

        /* 배경: 짙은 남색 + 종이 질감 느낌 */
        background-color: #1a1a22;
        background-image: url("data:image/svg+xml,%3Csvg width='40' height='40' viewBox='0 0 40 40' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='%23c5a059' fill-opacity='0.05' fill-rule='evenodd'%3E%3Cpath d='M0 38.59l2.83-2.83 1.41 1.41L1.41 40H0v-1.41zM0 1.4l2.83 2.83 1.41-1.41L1.41 0H0v1.41zM38.59 40l-2.83-2.83 1.41-1.41L40 38.59V40h-1.41zM40 1.41l-2.83 2.83-1.41-1.41L38.59 0H40v1.41zM20 18.6l2.83-2.83 1.41 1.41L21.41 20l2.83 2.83-1.41 1.41L20 21.41l-2.83 2.83-1.41-1.41L18.59 20l-2.83-2.83 1.41-1.41L20 18.59z'/%3E%3C/g%3E%3C/svg%3E");
        border: 1px solid #5a4a30;
        border-radius: 10px 0 0 10px;
        z-index: 10000;
        transition: right 0.5s cubic-bezier(0.19, 1, 0.22, 1);
        box-shadow: -5px 5px 15px rgba(0,0,0,0.6);

        /* 스크롤바 디자인 (웹킷 브라우저용) */
        scrollbar-width: thin;
        scrollbar-color: #5a4a30 #1a1a22;
    }

    /* 패널 내부 스크롤바 커스텀 */
    .side-panel::-webkit-scrollbar {
        width: 6px;
    }
    .side-panel::-webkit-scrollbar-track {
        background: #1a1a22; 
    }
    .side-panel::-webkit-scrollbar-thumb {
        background: #5a4a30; 
        border-radius: 3px;
    }
    .side-panel::-webkit-scrollbar-thumb:hover {
        background: #c5a059; 
    }

    /* 패널 내부 이중 테두리 (장식용) */
    .panel-inner-border {
        border: 2px double #c5a059; /* 금색 이중선 */
        margin: 5px;
        /* 높이 계산 수정: 스크롤 시 내용물 보호 */
        min-height: calc(100% - 14px); 
        border-radius: 6px 0 0 6px;
        background: rgba(0,0,0,0.2);
    }

    #side-panel-toggle:checked ~ .side-panel {
        right: 0;
    }

    #side-panel-toggle:checked ~ .floating-btn {
        right: 320px;
        background: #2a2a35;
    }

    /* 3. 헤더 디자인 */
    .panel-header {
        text-align: center;
        padding: 15px 10px 5px 10px;
    }

    .panel-header h2 {
        font-family: 'Cinzel', serif; /* 없으면 serif로 대체됨 */
        margin: 0;
        font-size: 18px;
        color: #ffd700; /* 밝은 금색 */
        text-shadow: 0 2px 4px rgba(0,0,0,0.5);
        letter-spacing: 1px;
    }

    .ornament-line {
        font-size: 12px;
        color: #7a6a4a;
        margin-top: 5px;
    }

    /* 4. 내용물 디자인 */
    .panel-body {
        padding: 15px;
    }

    .setting-row {
        display: flex;
        flex-direction: column;
        gap: 8px;
        margin-bottom: 5px;
    }

    .setting-title {
        font-size: 15px;
        color: #eee;
        border-left: 3px solid #c5a059;
        padding-left: 8px;
    }

    .setting-desc {
        font-size: 11px;
        color: #a09080;
        font-style: italic;
        margin-left: 11px;
    }

    .current-status {
        font-size: 11px;
        margin-left: 11px;
        margin-top: 4px;
        color: #b0b0b0;
    }

    /* ON 상태: 밝은 금색 */
    .status-on {
        color: #ffd700;
        font-weight: bold;
        text-shadow: 0 0 5px rgba(255, 215, 0, 0.4);
    }

    /* OFF 상태: 어두운 회색 */
    .status-off {
        color: #666;
    }

    /* 5. 버튼 커스터마이징 (RisuAI 버튼 강제 스타일링) */
    .setting-controls {
        display: flex;
        gap: 8px;
        justify-content: flex-end;
        margin-top: 5px;
    }

    /* 버튼 스타일 덮어쓰기 */
    .setting-controls button {
        background: linear-gradient(to bottom, #3a3a4a, #20202a) !important;
        border: 1px solid #7a6a4a !important;
        color: #d0c0a0 !important;
        font-family: serif !important;
        font-size: 11px !important;
        padding: 4px 12px !important;
        border-radius: 4px !important;
        cursor: pointer !important;
        transition: all 0.2s !important;
        box-shadow: inset 0 1px 0 rgba(255,255,255,0.1) !important;
    }

    .setting-controls button:hover {
        border-color: #ffd700 !important;
        color: #fff !important;
        box-shadow: 0 0 5px rgba(197, 160, 89, 0.5) !important;
    }

    .divider-ornament {
        height: 1px;
        background: linear-gradient(90deg, transparent, #5a4a30, transparent);
        margin: 15px 0;
    }

/* --- 모바일 전용 스타일 (수정됨) --- */
    @media (max-width: 600px) {
        /* 1. 패널 너비 줄이기 및 높이 제한 */
        .side-panel {
            width: 260px;
            right: -280px; 

            /* [중요] 모바일에서 위쪽을 조금 더 올려서 공간 확보 */
            top: 10%; 

            /* [중요] 내용이 화면보다 길어지면 잘리지 않고 스크롤되도록 설정 */
            max-height: 85vh; 
            overflow-y: auto; 
        }

        /* 2. 패널 열렸을 때 버튼 위치 재조정 */
        #side-panel-toggle:checked ~ .floating-btn {
            right: 260px; 
        }

        /* 3. 버튼 크기 및 위치 미세 조정 (터치하기 좋게) */
        .floating-btn {
            top: 12%; /* 버튼 위치도 패널에 맞춰 약간 올림 */
            width: 40px;
            height: 40px;
            line-height: 40px;
            font-size: 18px;
        }

        .floating-btn:hover {
            width: 40px; 
        }

        /* 4. 내부 글자 크기 최적화 */
        .panel-header h2 { font-size: 16px; }
        .setting-title { font-size: 14px; }
        .setting-desc { font-size: 10px; }
    }    
</style>
</body>{{/if}}
